mapper.select:
SELECT benefit_id AS benefitId, category, title, discount_summary AS discountSummary, period_start AS validFrom, period_end AS validTo, target_text AS target, content, usage_method AS method, remark_text AS precautions, detail_image_url AS detailImageUrl, source_url AS sourceUrl FROM leave_benefit WHERE active_yn = TRUE AND (period_start IS NULL OR period_start <= #{referenceDate}) AND (period_end IS NULL OR period_end >= #{referenceDate})
AND category = #{category}
ORDER BY category, display_order, benefit_id
